<template>
    <div v-if="categories.length" :class="{ row: vertical }">
        <div :class="{ 'md:col-4': vertical }">
            <ul
                class="nav nav-pills"
                :class="[styleClasses, {
                    'nav-pills-icons': hasCategoryIcons,
                    'flex-column': vertical,
                    'justify-content-center': !vertical && centered,
                    'w-100': vertical || centered,
                }]"
                role="tablist"
                :aria-label="label"
                :aria-orientation="vertical ? 'vertical' : undefined"
            >
                <li v-for="(category, index) in categories" :key="category.tabId" class="nav-item" role="presentation">
                    <button
                        :id="elementId('tab', index)"
                        type="button"
                        class="nav-link"
                        :class="{ active: category.tabId === activeTab, 'w-100': vertical }"
                        role="tab"
                        :aria-controls="elementId('panel', index)"
                        :aria-selected="category.tabId === activeTab"
                        :tabindex="category.tabId === activeTab ? 0 : -1"
                        :disabled="category.disabled"
                        @click="setActiveTab(category.tabId)"
                        @keydown="handleTabKeydown($event, category.tabId)"
                    >
                        <i v-if="category.icon" class="material-icons" aria-hidden="true">{{ category.icon }}</i>
                        <span>{{ category.name }}</span>
                    </button>
                </li>
            </ul>
        </div>

        <div :class="{ 'md:col-8': vertical }">
            <div class="tab-content tab-space" :class="{ 'md:pt-0': vertical }">
                <div
                    v-for="(category, index) in categories"
                    :id="elementId('panel', index)"
                    :key="category.tabId"
                    class="tab-pane"
                    :class="{ active: category.tabId === activeTab }"
                    role="tabpanel"
                    :aria-labelledby="elementId('tab', index)"
                    :hidden="category.tabId !== activeTab"
                    tabindex="0"
                >
                    <slot :name="category.tabId">{{ category.name }}</slot>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { useId } from 'vue';

export default {
    name: 'PageCategories',
    props: {
        categories: { type: Array, required: true },
        styleClasses: { type: String, default: 'nav-pills-primary' },
        label: { type: String, default: 'Kategorijas' },
        centered: { type: Boolean, default: true },
        vertical: Boolean,
        defaultActive: { type: String, default: null },
    },
    emits: ['change'],
    setup() {
        return { instanceId: useId() };
    },
    data() {
        return { selectedTabId: this.defaultActive };
    },
    computed: {
        hasCategoryIcons() {
            return this.categories.some((category) => category.icon);
        },
        enabledCategories() {
            return this.categories.filter((category) => !category.disabled);
        },
        activeTab() {
            const selected = this.enabledCategories.find((category) => category.tabId === this.selectedTabId);

            return selected?.tabId ?? this.enabledCategories[0]?.tabId ?? null;
        },
    },
    methods: {
        elementId(kind, index) {
            return `${this.instanceId}-${kind}-${index}`;
        },
        setActiveTab(tabId) {
            if (tabId === this.activeTab || !this.enabledCategories.some((category) => category.tabId === tabId)) {
                return;
            }

            this.selectedTabId = tabId;
            this.$emit('change', tabId);
        },
        handleTabKeydown(event, tabId) {
            const tabs = this.enabledCategories;
            const index = tabs.findIndex((category) => category.tabId === tabId);
            if (index === -1) {
                return;
            }

            const direction = !this.vertical && getComputedStyle(event.currentTarget).direction === 'rtl' ? -1 : 1;
            const destinations = {
                [this.vertical ? 'ArrowUp' : 'ArrowLeft']: (index - direction + tabs.length) % tabs.length,
                [this.vertical ? 'ArrowDown' : 'ArrowRight']: (index + direction + tabs.length) % tabs.length,
                Home: 0,
                End: tabs.length - 1,
            };

            if (!Object.hasOwn(destinations, event.key) || event.altKey || event.ctrlKey || event.metaKey) {
                return;
            }

            event.preventDefault();
            const nextTab = tabs[destinations[event.key]];
            this.setActiveTab(nextTab.tabId);
            const nextIndex = this.categories.indexOf(nextTab);
            document.getElementById(this.elementId('tab', nextIndex))?.focus();
        },
    },
};
</script>

<style scoped>
    :is(.nav-link, .tab-pane):focus-visible {
        outline: var(--focus-ring);
        outline-offset: 2px;
    }
</style>
