<template>
    <div class="accordion" :class="styleClasses">
        <div
            v-for="category in categories"
            :key="category.tabId"
            class="accordion-item"
        >
            <h2 class="accordion-header">
                <button
                    type="button"
                    class="accordion-button"
                    :class="{ collapsed: !isActive(category.tabId) }"
                    :aria-expanded="isActive(category.tabId)"
                    :aria-controls="`${category.tabId}-content`"
                    @click="toggle(category.tabId)"
                >
                    <i
                        v-if="category.icon"
                        class="material-icons accordion-icon"
                    >
                        {{ category.icon }}
                    </i>

                    {{ category.name }}
                </button>
            </h2>

            <div
                :id="`${category.tabId}-content`"
                class="accordion-collapse"
                :class="{ show: isActive(category.tabId) }"
                role="region"
            >
                <div class="accordion-body">
                    <slot :name="category.tabId" :category="category">
                        {{ category.name }}
                    </slot>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
export default {
    name: 'Accordion',

    props: {
        categories: {
            type: Array,
            required: true,
        },

        styleClasses: {
            type: String,
            default: 'accordion-primary',
        },

        defaultActive: {
            type: String,
            default: null,
        },

        collapsible: {
            type: Boolean,
            default: true,
        },
    },

    emits: ['change'],

    data() {
        return {
            activeItem:
                this.defaultActive ??
                this.categories[0]?.tabId ??
                null,
        };
    },

    methods: {
        isActive(tabId) {
            return this.activeItem === tabId;
        },

        toggle(tabId) {
            if (this.isActive(tabId) && this.collapsible) {
                this.setActiveItem(null);
                return;
            }

            this.setActiveItem(tabId);
        },

        setActiveItem(tabId) {
            this.activeItem = tabId;
            this.$emit('change', tabId);
        },
    },
};
</script>

<style scoped>
.accordion {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.accordion-item {
    overflow: hidden;
    border: 1px solid #ddd;
    border-radius: 4px;
    background: #fff;
}

.accordion-header {
    margin: 0;
}

.accordion-button {
    display: flex;
    align-items: center;
    width: 100%;
    padding: 12px 15px;
    border: 0;
    background: #3d86c3;
    color: #fff;
    font-size: 12px;
    font-weight: 500;
    line-height: 24px;
    text-align: left;
    text-transform: uppercase;
    cursor: pointer;
    transition: all 0.3s;
    user-select: none;
}

.accordion-button:focus {
    outline: none;
    box-shadow: none;
}

.accordion-button:focus-visible {
    outline: none;
    box-shadow: 0 0 0 3px rgba(61, 134, 195, 0.3);
}

.accordion-button.collapsed {
    background: #fff;
    color: #555;
}

.accordion-button::after {
    width: 8px;
    height: 8px;
    margin-left: auto;
    border-right: 2px solid currentColor;
    border-bottom: 2px solid currentColor;
    content: "";
    transform: rotate(225deg);
    transition: transform 0.3s;
}

.accordion-button.collapsed::after {
    transform: rotate(45deg);
}

.accordion-icon {
    margin-right: 8px;
    font-size: 20px;
}

.accordion-collapse {
    display: grid;
    grid-template-rows: 0fr;
    visibility: hidden;
    transition:
        grid-template-rows 0.3s ease,
        visibility 0.3s;
}

.accordion-collapse.show {
    grid-template-rows: 1fr;
    visibility: visible;
}

.accordion-body {
    min-height: 0;
    overflow: hidden;
    padding: 0 15px;
    transition: padding 0.3s ease;
}

.accordion-collapse.show .accordion-body {
    padding-top: 15px;
    padding-bottom: 15px;
}

.accordion-material {
    gap: 0;
}

.accordion-material .accordion-item {
    border: 0;
    border-radius: 0;
    background: transparent;
}

.accordion-material .accordion-button {
    padding: .875rem 1rem .625rem 0;
    border-bottom: 1px solid var(--border-color);
    background: transparent;
    color: light-dark(#c2185b, #ff80ab);
    font-size: .875rem;
    font-weight: 400;
    line-height: 1.5;
    text-transform: none;
}

.accordion-material .accordion-button.collapsed {
    color: var(--fg-body);
}

.accordion-material .accordion-button::after {
    background-image: none;
}

.accordion-material .accordion-body {
    padding-inline: 0;
    font-size: .875rem;
}
</style>
